import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long[] out = new long[n + 1];
        for (int left = 0; left < n; left++) {
            long total = 0;
            for (int right = left; right < n; right++) {
                total += a[right];
                long size = right - left + 1;
                if (total % size == 0) out[(int) (total / size)]++;
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int x = 1; x <= n; x++) sb.append(out[x]).append(x == n ? '\n' : ' ');
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	out := make([]int64, n+1)
	for left := 0; left < n; left++ {
		total := int64(0)
		for right := left; right < n; right++ {
			total += a[right]
			size := int64(right - left + 1)
			if total%size == 0 {
				out[total/size]++
			}
		}
	}
	var buf []byte
	for x := 1; x <= n; x++ {
		buf = strconv.AppendInt(buf, out[x], 10)
		if x == n {
			buf = append(buf, '\n')
		} else {
			buf = append(buf, ' ')
		}
	}
	os.Stdout.Write(buf)
}
